import { Component } from "obsidian";
import { DictionaryEditor } from "../../src/dictionary-editor";
import { ReviewPlanEditor } from "../../src/review-plan-editor";
import { renderCollectionReview } from "../../src/review-collection-controls";
import { DEFAULT_SETTINGS } from "../../src/default-settings";
import { createI18n } from "../../src/i18n";
import { ReviewStartModal } from "../../src/review-start-modal";

const tick = () => new Promise(resolve => setTimeout(resolve, 0));
export async function checkDictionaryCollections(check: (value: unknown, message: string) => void): Promise<void> {
  const folder = "Words/" + "LongDictionaryPath".repeat(5);
  const files = [{path:"Hub.md"},{path:"Single.md"}];
  const app = {vault:{configDir:"custom-config",getAllLoadedFiles:()=>[folder,"Other","Other/Custom"].map(path=>({path,children:[]})).concat(files as any),getMarkdownFiles:()=>files},metadataCache:{getFileCache:()=>({tags:[{tag:"#novel"}]})}} as any;
  const t = createI18n(()=>"zh").t;
  const dictionary = {id:"stable",name:"Novel",folder,template:"",sources:[{kind:"folder",value:folder},{kind:"file",value:"Single.md"},{kind:"links",value:"Hub.md"},{kind:"tag",value:"novel"}],color:"#abcd12",opacity:.3} as any;
  const original = JSON.stringify(dictionary);
  let saved:any=null;
  const editor=new DictionaryEditor(app,{t,templateProvider:{templaterTemplateFor:()=>null}},dictionary,async row=>{saved=row;});
  editor.open();
  const root=editor.contentEl;
  const sourceRows=()=>[...root.querySelectorAll<HTMLElement>(".lexis-collection-source")];
  check(sourceRows().map(row=>row.querySelector("button")?.textContent).join("|")==="文件夹|单个文件|目录文件内双链|标签","dictionary editor offers the four shared source types in one collection");
  check(sourceRows().every(row=>row.querySelector("input"))&&document.documentElement.scrollWidth<=window.innerWidth,"mixed dictionary sources fit mobile and desktop without horizontal overflow");
  const source=sourceRows()[0].querySelector<HTMLInputElement>("input")!;
  source.value="#characters";source.dispatchEvent(new Event("input"));
  check(sourceRows()[0].querySelector("button")?.textContent==="标签","typing # switches the source type to tags immediately");
  check(JSON.stringify(dictionary)===original&&saved===null,"dictionary editing keeps the persisted collection untouched until Save");
  editor.close();
  check(JSON.stringify(dictionary)===original&&saved===null,"canceling dictionary edits preserves paths, identity and appearance");
  const editAgain=new DictionaryEditor(app,{t,templateProvider:{templaterTemplateFor:()=>null}},dictionary,async row=>{saved=row;});
  editAgain.open();
  const name=editAgain.contentEl.querySelector<HTMLInputElement>("input")!;
  name.value="Renamed";name.dispatchEvent(new Event("input"));
  editAgain.contentEl.querySelector<HTMLButtonElement>('button[aria-label="保存"]')!.click();
  await tick();
  check(saved?.id==="stable"&&saved.name==="Renamed"&&saved.sources.length===4&&saved.color==="#abcd12"&&saved.opacity===.3,"saving a combined dictionary preserves stable identity and appearance");
  check(dictionary.name==="Novel","editor commits a replacement draft, never mutates the original row");
  const fresh = new DictionaryEditor(app,{t,templateProvider:{templaterTemplateFor:()=>null}},null,async()=>{});
  fresh.open();
  const draftRoot=fresh.contentEl;
  const folderSource=draftRoot.querySelector<HTMLInputElement>(".lexis-collection-source input")!;
  const destination=[...draftRoot.querySelectorAll<HTMLElement>(".setting-item")].find(row=>row.querySelector(".setting-item-name")?.textContent==="新词保存文件夹")!.querySelector<HTMLInputElement>("input")!;
  const suggest=(globalThis as any).__lexisSuggests.findLast((item:any)=>item.input===folderSource);
  suggest.selectSuggestion(folder);
  check(destination.value===folder,"choosing a folder source automatically fills the capture folder without another search control");
  folderSource.value="O";folderSource.dispatchEvent(new Event("input"));
  folderSource.value="Other";folderSource.dispatchEvent(new Event("input"));
  check(destination.value==="Other","an automatically filled destination follows a changed folder source");
  destination.value="Other/Custom";destination.dispatchEvent(new Event("input"));
  folderSource.value=folder;folderSource.dispatchEvent(new Event("input"));
  check(destination.value==="Other/Custom","source changes never overwrite a manually chosen capture folder");
  destination.value="";destination.dispatchEvent(new Event("input"));
  folderSource.value="Other";folderSource.dispatchEvent(new Event("input"));
  check(destination.value==="","an explicitly cleared capture folder remains empty");
  check(draftRoot.querySelector('button[data-icon="plus"]')?.getAttribute("aria-label")==="添加来源"&&draftRoot.querySelector('button[data-icon="check"]')?.getAttribute("aria-label")==="保存","source add and save use labeled plus/check icons instead of text buttons");
  check(!draftRoot.querySelector('input[type="search"]')&&draftRoot.querySelectorAll("input").length===4,"dictionary paths use direct text inputs with inline candidates, not extra search widgets");
  fresh.close();
  const plan={id:"plan",name:"Daily",dictionaryIds:["stable"],content:"syntax" as const};
  const settings=structuredClone({...DEFAULT_SETTINGS,dataFolder:"99_assets/plugin-data/lexis",dicts:[dictionary],reviewPlans:[plan]});
  let writes=0;
  const host={settings,t,reviewDashboard:{refresh(){}},saveSettings:async()=>{writes++;}} as any;
  const planEditor=new ReviewPlanEditor(app,host,plan);
  planEditor.open();
  check(!!planEditor.contentEl.querySelector(".lexis-dictionary-picker")&&!!planEditor.contentEl.querySelector('input[type="date"]'),"plans reuse dictionary scope and offer an optional deadline");
  check(planEditor.contentEl.textContent?.includes('99_assets/plugin-data/lexis/reviews'),'plan storage hint uses the configured visible learning data folder');
  check(writes===0,"opening a review plan never persists draft choices");
  const row=(label:string)=>[...planEditor.contentEl.querySelectorAll<HTMLElement>('.setting-item')].find(item=>item.querySelector('.setting-item-name')?.textContent===label)!;
  row('范围').querySelector<HTMLButtonElement>('button')!.click();
  (globalThis as any).__lexisMenus.at(-1).items.find((item:any)=>item.title==='单个文件').click();
  const fileInput=row('范围').querySelector<HTMLInputElement>('input')!;
  const fileSuggest=(globalThis as any).__lexisSuggests.findLast((item:any)=>item.input===fileInput);
  check(fileSuggest.getSuggestions('Sing').includes('Single.md'),'single-file plan input offers inline fuzzy candidates');
  fileSuggest.selectSuggestion('Single.md');
  row('模式').querySelector<HTMLButtonElement>('button')!.click();
  const quantity=row('每日目标').querySelector<HTMLInputElement>('input')!;quantity.value='2';quantity.dispatchEvent(new Event('input'));
  const rounds=row('遍数').querySelector<HTMLInputElement>('input')!;rounds.value='3';rounds.dispatchEvent(new Event('input'));
  check(writes===0&&settings.reviewPlans[0].dictionaryIds?.[0]==='stable','switching scope and practice options remains a draft');
  [...planEditor.contentEl.querySelectorAll<HTMLButtonElement>('button')].find(button=>button.textContent===t('dashboard.save'))!.click();
  await tick();
  check(writes===1&&settings.reviewPlans[0].scope==='current'&&settings.reviewPlans[0].file==='Single.md'&&settings.reviewPlans[0].dictionaryIds===undefined&&settings.reviewPlans[0].mode==='cram'&&settings.reviewPlans[0].rounds===3,'saving replaces dictionary scope with single-file practice without adding a dictionary');
  planEditor.close();
  const home=document.body.createDiv({cls:"lexis-home"});
  const component=new Component();component.load();
  let options:any=null;
  renderCollectionReview(home,app,{...host,openReview:async value=>{options=value;}},component);
  check(home.querySelectorAll(".lexis-dictionary-picker").length===1&&home.querySelectorAll('.lexis-review-setup').length===1,"one-off review reuses the same scope, mode and count controls");
  [...home.querySelectorAll<HTMLButtonElement>("button")].find(button=>button.textContent===t("home.start"))!.click();
  check(options?.dictionaryIds===null&&options.content==="syntax","one-off review passes collection scope and content mode independently");
  check(home.scrollWidth<=home.clientWidth+1&&document.documentElement.scrollWidth<=window.innerWidth,"shared review collection controls fit the phone viewport");
  component.unload();home.remove();
  let started:any=null;
  const beforeCancel=JSON.stringify(settings);
  const modal=new ReviewStartModal(app,{...host,openReview:async value=>{started=value;}},{scope:'current',file:'Single.md',content:'syntax',mode:'cram',batchSize:null,rounds:1},'Single.md');
  modal.open();
  check(!modal.contentEl.querySelector('.lexis-dictionary-picker')&&modal.contentEl.textContent?.includes('Single.md'),'current-file start dialog keeps scope fixed without requiring a dictionary');
  const fields=[...modal.contentEl.querySelectorAll<HTMLInputElement>('input[type="number"]')];
  fields[0].value='1';fields[0].dispatchEvent(new Event('input'));fields[1].value='2';fields[1].dispatchEvent(new Event('input'));
  check(JSON.stringify(settings)===beforeCancel&&started===null,'start-dialog edits never write settings or begin review before confirmation');
  modal.close();
  check(JSON.stringify(settings)===beforeCancel,'canceling the start dialog leaves plans and histories unchanged');
}
